#!/bin/sh
# ============================================================================
# dsh-ios +ios9 —— 预装 @xmanrui/dsh-im 5.10.0（10 渠道 IM 机器人插件）
#
# 症状：照官方 README 在 iPhone 终端执行
#   dsh plugin --profile web add -w @xmanrui/dsh-im
# 必然「退出码 127」：dsh 的 plugin 子命令把参数转发给 pnpm，而 rootless
# iPhone 上没有 pnpm/npm/npx/corepack/git。官方 install 还要求 Node >=22.19，
# 本包内置的是 iPhone X / A11 实测可用的 Node 22.12.0。
#
# 本脚本完全绕开设备端包管理：
#   1) 内嵌裁剪后的插件 + 114 个运行时依赖（1275 文件 / 22.9MB / 0 个 .node），
#      用「插件私有 node_modules」隔离，不污染宿主 dsh / +ios7 QQ Bot 的版本；
#   2) 设备端给 lib/index.js 打「零 JIT / 无 WASM」补丁（见下方 [关键修复]）；
#   3) 追加一行 - insert: { id: xmanrui-dsh-im } 到 $DSH_HOME/cordis.patch.yml；
#   4) 建 profile -> 包目录的 ESM 解析链路（真机必需，见下方 [真机坑]）；
#   5) 顺带修 +ios8 的「重启丢对话」，若本机尚未修。
#
# [关键修复] A11 的 tier.sh 最终档是 nowasm（--jitless --no-expose-wasm），
# 而 --jitless 会连带禁用 WebAssembly（实测连 node:vm 都取不到）。dsh-im
# 把 WhatsApp/Baileys 的 libsignal WASM glue 内联进了 lib/index.js，并在模块
# 顶层执行 `var JCe=new VC` —— 无 WASM 时整包 import 直接抛
#   TypeError: ge.lthashantitampering_new is not a function
# Cordis 只报「1 entry did not activate」，web 照常监听，但「设置 → IM机器人」
# 入口和全部渠道消失（最坑的假故障）。补丁把顶层单例惰性化、给 history-sync
# 的 lthash 收尾加 null 保护。native 档走 try 成功分支，行为与官方包一致。
# 唯一降级：WhatsApp 的「加密历史同步哈希」在零 JIT 档返回占位值；其余 9 个
# 渠道（飞书/微信/企微/钉钉/QQ/Slack/Telegram/Discord/Matrix）完全可用。
#
# [真机坑] dsh 的 ESM resolver 以 profile 目录为基准解析包名，插件实体却在
# 包目录 /var/jb/usr/lib/dsh/node_modules —— 不建链路真机必然
# ERR_MODULE_NOT_FOUND。构建机常因目录层级巧合给假绿灯，这里做强校验。
#
# 已在 x86 Linux 按 iOS 目录布局 1:1 模拟验证：
#   native / nowasm 两档均 0 did-not-activate、0 failed-import；
#   index.html 的 client graph 含 {"id":"@xmanrui/dsh-im","url":".../client.js"}，
#   证明「设置 → IM机器人」前端入口确实被注入。
#
# 用法：sh install-im.sh             安装（幂等，可重复跑）
#       sh install-im.sh --status   查状态
#       sh install-im.sh --remove  卸载并回滚
#
# ！！！装完必须 Ctrl+C 退出当前 dsh，再重新敲 dsh。刷新网页无效。
# ============================================================================
set -eu

JB=/var/jb
D="$JB/usr/lib/dsh"
NM="$D/node_modules"
NODE="$D/bin/node"
BIN="$NM/@deepseek-ai/dsh/lib/bin.js"
PKG="$NM/@xmanrui/dsh-im"
HOME_DSH="${DSH_HOME:-$JB/var/mobile/.dsh}"
UPATCH="$HOME_DSH/cordis.patch.yml"
MARK="$D/.im-installed"
TMP="${TMPDIR:-/var/tmp}/dsh-im-install.$$"

MODE=install
case "${1:-}" in
    --remove) MODE=remove ;;
    --status) MODE=status ;;
    "")      ;;
    *) echo "用法: sh install-im.sh [--status|--remove]" >&2; exit 2 ;;
esac

if [ ! -L "$JB" ] || [ ! -x "$NODE" ] || [ ! -f "$BIN" ]; then
    echo "[FAIL] 越狱未激活，或 dsh-ios 的 .deb 没装（找不到 $BIN）。" >&2
    exit 1
fi

if [ "$MODE" = status ]; then
    if [ -f "$PKG/lib/index.js" ]; then S1=已安装; else S1=缺失; fi
    if grep -q "dsh-ios +ios9" "$PKG/lib/index.js" 2>/dev/null; then S2=已打; else S2=未打; fi
    if grep -q "id: xmanrui-dsh-im" "$UPATCH" 2>/dev/null; then S3=已挂载; else S3=未挂载; fi
    if [ -e "$HOME_DSH/node_modules/@xmanrui/dsh-im/lib/index.js" ]; then S4=通; else S4=断; fi
    echo "插件文件 : $S1"
    echo "零JIT补丁: $S2"
    echo "用户层   : $S3"
    echo "解析链路 : $S4"
    if [ -f "$NM/@deepseek-ai/dsh-session-persistence-jsonl/lib/index.js" ]; then
        if grep -q 'const DEFAULT_COMPRESSION = "none";' "$NM/@deepseek-ai/dsh-session-persistence-jsonl/lib/index.js"; then
            echo "会话修复 : 已修"; else echo "会话修复 : 未修（跑 sh fix-session.sh）"; fi
    fi
    exit 0
fi

if [ "$MODE" = remove ]; then
    rm -rf "$PKG" "$MARK"
    if [ -f "$UPATCH.pre-im.bak" ]; then
        cp "$UPATCH.pre-im.bak" "$UPATCH"; rm -f "$UPATCH.pre-im.bak"
        echo "[ ok ] 已恢复 $UPATCH"
    else
        # 整块删除（不能逐行 grep -v：会留下孤立的 name:/config: 行，
        # 把 - insert: 拆成半截，dsh 启动直接 fatal:
        #   TypeError: patch.insert?.forEach is not a function）
        if [ -f "$UPATCH" ] && grep -q "id: xmanrui-dsh-im" "$UPATCH"; then
            cat > "$TMP.rmpatch.cjs" <<'DSH_IM_RMPATCH_EOF'
const fs=require('node:fs');const p=process.argv[2];
const lines=fs.readFileSync(p,'utf8').split('\n');
let blocks=[],cur=[];
for(const l of lines){
  if(/^-\s/.test(l)&&cur.length){blocks.push(cur);cur=[l];}
  else cur.push(l);
}
if(cur.length)blocks.push(cur);
const kept=blocks.filter(b=>!b.some(x=>/id:\s*xmanrui-dsh-im/.test(x)));
fs.writeFileSync(p,kept.map(b=>b.join('\n')).join('\n').replace(/\n+$/,'\n'));
DSH_IM_RMPATCH_EOF
            "$NODE" "$TMP.rmpatch.cjs" "$UPATCH" || true
            rm -f "$TMP.rmpatch.cjs" 2>/dev/null || true
            echo "[ ok ] 已从 $UPATCH 整块移除本插件（其它行保留）"
        fi
    fi
    rmdir "$NM/@xmanrui" 2>/dev/null || true
    rm -f "$TMP" "$TMP.tar" "$TMP.b64" "$TMP.patch.cjs" 2>/dev/null || true
    echo "[ ok ] dsh-im 已移除。Ctrl+C 重启 dsh 生效。"
    exit 0
fi

echo "==> 预装 @xmanrui/dsh-im 5.10.0（无需 pnpm / 无需重传 118MB deb）"
echo
# 只备份「不含本插件」的原版，避免二次安装把已含插件的配置存成备份
if [ -f "$UPATCH" ] && [ ! -f "$UPATCH.pre-im.bak" ] \
   && ! grep -q "id: xmanrui-dsh-im" "$UPATCH" 2>/dev/null; then
    cp "$UPATCH" "$UPATCH.pre-im.bak" 2>/dev/null || true
fi
mkdir -p "$HOME_DSH" "$NM" 2>/dev/null || true

# ---- 1) 解出内嵌依赖树 ----
cat > "$TMP.b64" <<'DSH_IM_DATA_EOF'
