cat > "$TMP.patch.cjs" <<'DSH_IM_PATCH_EOF'
const fs=require('node:fs');const p=process.argv[2];let s=fs.readFileSync(p,'utf8');
const pairs=[['var JCe=new VC;','var JCe=null;try{JCe=new VC}catch(_dshImWasmErr){}/* dsh-ios +ios9: libsignal WASM unavailable */'],
['let e=JCe.subtractThenAdd(t,a,o);','let e=JCe?JCe.subtractThenAdd(t,a,o):Buffer.alloc(128);/* dsh-ios +ios9: degrade */']];
let ok=0;for(const [o,n] of pairs){const c=s.split(o).length-1;
if(c===1){s=s.replace(o,n);ok++;}
else if(c===0&&s.includes('dsh-ios +ios9')){ok++;}
else{console.error('[FAIL] 补丁模式命中 '+c+' 次，拒绝打坏包');process.exit(1);}}
fs.writeFileSync(p,s);console.log('[ ok ] 零 JIT 补丁就位（'+ok+'/2）');
DSH_IM_PATCH_EOF

# node 负责 base64 解码 + gunzip（不依赖 iOS 上的 base64/gzip 命令）
"$NODE" -e "const fs=require('node:fs'),z=require('node:zlib');
const s=fs.readFileSync(process.argv[1],'utf8').replace(/\s/g,'');
fs.writeFileSync(process.argv[2],z.gunzipSync(Buffer.from(s,'base64')));" \
    "$TMP.b64" "$TMP.tar" || { echo "[FAIL] 解码失败" >&2; exit 1; }
rm -rf "$PKG"
if ! tar xf "$TMP.tar" -C "$NM" 2>"$TMP.tarerr"; then
    echo "[FAIL] 解包失败（设备缺少 tar？）：$(cat "$TMP.tarerr" | head -2)" >&2
    echo "       已保留 $TMP.tar，可手动：tar xf $TMP.tar -C $NM" >&2
    exit 1
fi
echo "[ ok ] 插件与 114 个运行时依赖已就位（1275 文件 / 0 个 .node）"

# ---- 2) 打零 JIT 补丁（addon 存的是官方原版，设备端现场打，幂等） ----
"$NODE" "$TMP.patch.cjs" "$PKG/lib/index.js" || exit 1

# ---- 3) 注册插件到 home 级用户 patch（保留 im-qqbot 等已有行） ----
if grep -q "id: xmanrui-dsh-im" "$UPATCH" 2>/dev/null; then
    echo "[skip] $UPATCH 已含 xmanrui-dsh-im"
else
    if [ ! -f "$UPATCH" ]; then
        cp "$PKG/cordis.patch.yml" "$UPATCH"
    else
        # flow-style 空数组 [] 会让追加变成非法 YAML，先去掉
        if grep -qE "^[[:space:]]*\[\][[:space:]]*$" "$UPATCH"; then
            grep -vE "^[[:space:]]*\[\][[:space:]]*$" "$UPATCH" > "$UPATCH.tmp" 2>/dev/null || true
            mv "$UPATCH.tmp" "$UPATCH" 2>/dev/null || true
        fi
        cat "$PKG/cordis.patch.yml" >> "$UPATCH"
    fi
    echo "[ ok ] 已把 xmanrui-dsh-im 追加到 $UPATCH"
fi

# ---- 4) ESM 解析链路（真机必需，与 +ios7 QQ Bot 共用） ----
NMHOME="$HOME_DSH/node_modules"
if [ -L "$NMHOME" ] && [ ! -e "$NMHOME" ]; then rm -f "$NMHOME" 2>/dev/null || true; fi
if [ ! -e "$NMHOME" ] && [ ! -L "$NMHOME" ]; then
    ln -s "$NM" "$NMHOME" 2>/dev/null || true
fi
if [ ! -e "$NMHOME/@xmanrui/dsh-im/lib/index.js" ]; then
    mkdir -p "$NMHOME/@xmanrui" 2>/dev/null || true
    ln -s "$PKG" "$NMHOME/@xmanrui/dsh-im" 2>/dev/null || true
fi
if [ ! -e "$NMHOME/@xmanrui/dsh-im/lib/index.js" ]; then
    echo "[FAIL] 建不起 profile -> 插件包的解析链路，真机会 ERR_MODULE_NOT_FOUND。" >&2
    exit 1
fi
echo "[ ok ] ESM 解析链路已建立"

# ---- 5) 顺带修 +ios8「重启丢对话」（若本机尚未修） ----
PJ="$NM/@deepseek-ai/dsh-session-persistence-jsonl/lib/index.js"
if [ -f "$PJ" ] && ! grep -q 'const DEFAULT_COMPRESSION = "none";' "$PJ"; then
    if [ -f "$D/fix-session.sh" ]; then
        sh "$D/fix-session.sh" >/dev/null 2>&1 && echo "[ ok ] 已顺带修复会话持久化" \
          || echo "[warn] 会话修复未完成，请手动跑 sh $D/fix-session.sh" >&2
    else
        "$NODE" -e "const fs=require('node:fs'),p=process.argv[1];
let s=fs.readFileSync(p,'utf8');s=s.replace('const DEFAULT_COMPRESSION = \"zstd\";','const DEFAULT_COMPRESSION = \"none\";');
fs.writeFileSync(p,s);" "$PJ" && echo "[ ok ] 已顺带把会话默认压缩改为 none"
    fi
fi

# ---- 6) 校验 ----
MISS=0
[ -f "$PKG/lib/index.js" ] || { echo "[FAIL] 缺 lib/index.js"; MISS=1; }
[ -f "$PKG/lib/client.js" ] || { echo "[FAIL] 缺 lib/client.js"; MISS=1; }
[ -f "$PKG/package.json" ] || { echo "[FAIL] 缺 package.json"; MISS=1; }
[ -f "$PKG/cordis.patch.yml" ] || { echo "[FAIL] 缺 cordis.patch.yml"; MISS=1; }
[ -f "$PKG/node_modules/@wecom/aibot-node-sdk/package.json" ] || { echo "[FAIL] 缺 node_modules/@wecom/aibot-node-sdk/package.json"; MISS=1; }
[ -f "$PKG/node_modules/undici/package.json" ] || { echo "[FAIL] 缺 node_modules/undici/package.json"; MISS=1; }
[ -f "$PKG/node_modules/qrcode/package.json" ] || { echo "[FAIL] 缺 node_modules/qrcode/package.json"; MISS=1; }
grep -q "dsh-ios +ios9" "$PKG/lib/index.js" || { echo "[FAIL] 零 JIT 补丁未生效"; MISS=1; }
[ "$MISS" -eq 0 ] || { echo "安装不完整，请重新运行本脚本。" >&2; exit 1; }
echo "[ ok ] 关键文件与补丁校验通过"

# 动态校验：让 dsh 自己 dump 配置树，确认插件行真的被组合进去。
# +ios10：Node 22.12 的 node:sqlite 需显式开关，否则 dsh-im 整包 import 失败
TIERFLAGS="--experimental-sqlite --disable-warning=ExperimentalWarning"
if [ -f "$D/fetch-shim.cjs" ]; then
    TIERFLAGS="$TIERFLAGS --jitless --no-expose-wasm --require $D/fetch-shim.cjs"
fi
# shellcheck disable=SC2086
if HOME="${HOME:-/var/mobile}" DSH_HOME="$HOME_DSH" "$NODE" $TIERFLAGS --expose-internals "$BIN" \
        --profile web --dump-config 2>/dev/null | grep -q "id: xmanrui-dsh-im"; then
    echo "[ ok ] dsh 配置树已包含 xmanrui-dsh-im（插件会被加载）"
else
    echo "[warn] 自动校验未完成（不影响安装）；可手动跑：dsh --dump-config | grep xmanrui"
fi

printf "%s\n" "+ios9" > "$MARK" 2>/dev/null || true
rm -f "$TMP" "$TMP.tar" "$TMP.b64" "$TMP.patch.cjs" "$TMP.tarerr" 2>/dev/null || true
echo
echo "==> 完成。接下来：Ctrl+C 退出当前 dsh，再重新敲 dsh。"
echo "    然后打开 设置 → IM机器人，按引导扫码或填机器人凭据。"
echo "    DeepSeek API Key 沿用工作台原有 LLM 配置，不用在这里填。"
echo "    临时不加载：DSH_IM=0 dsh   查状态：sh install-im.sh --status"
exit 0
